SELECT s.country, CASE WHEN s.city IN ('New York', 'Bangkok') THEN 'group_a' ELSE 'other' END AS city_group, ROUND((100 * SUM(CASE WHEN p.brand = 'Umbrella' THEN 1 ELSE 0 END)) / COUNT(*), 1) AS pct_umbrella, MAX(p.launch_date) AS last_launch_date FROM products p INNER JOIN suppliers s ON s.id = p.supplier_id GROUP BY s.country, CASE WHEN s.city IN ('New York', 'Bangkok') THEN 'group_a' ELSE 'other' END ORDER BY city_group DESC;
